  assert check(\"RHAISTRAT-9006\", os.path.join(tmp, \"artifacts\"),\n458\t                     comp) == [], \"self-contained bundling note must not fire\"\n459\t\n460\t        print(\"self-check OK: 7 checks fire on bad fixture, clean on good\")\n461\t        return 0\n462\t    finally:\n463\t        shutil.rmtree(tmp, ignore_errors=True)\n464\t\n465\t\n466\tdef main(argv=None):\n467\t    ap = argparse.ArgumentParser(description=__doc__)\n468\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n469\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n470\t    ap.add_argument(\"--components\",\n471\t                    default=\".context/rhai-components.txt\")\n472\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n473\t    args = ap.parse_args(argv)\n474\t\n475\t    if args.self_check:\n476\t        return _self_check()\n477\t    if not args.strat_id:\n478\t        ap.error(\"strat_id is required (unless --self-check)\")\n479\t\n480\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n481\t    if probs:\n482\t        for p in probs:\n483\t            print(\"VIOLATION: %s\" % p)\n484\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n485\t              \"complete\" % len(probs))\n486\t        return 1\n487\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n488\t    return 0\n489\t\n490\t\n491\tif __name__ == \"__main__\":\n492\t    sys.exit(main())\n493\t"}]},"parent_tool_use_id":"chatcmpl-tool-95ba045d32a00c6b","agent_id":"aed3d9bc59117f76c","session_id":"ca1a66b0-be22-44b3-9715-c3e9690708e5","uuid":"8717aadc-dad9-4779-9bfe-8e08bcf6d5dd","timestamp":"2026-10-26T08:37:49.388Z","tool_result_meta":[{"id":"chatcmpl-tool-9c34cf5384438060","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"general-purpose","task_description":"Decompose RHAISTRAT-9020"}
